mapper.select:
SELECT DISTINCT bod.id as delivery_id, bo.id, bo.order_id, bo.order_time, sdd.dict_label as status_label, bo.customer_name, bo.phone_number, bod.delivery_customer_name, bod.delivery_address as delivery_address, bo.delivery_plan_date, bo.payment_date, bo.ship_date, bo.delivery_date, bod.delivery_tracking_no, bod.delivery_phone_number, bod.invoice_unit, sdd2.dict_label as proxy_order_ch_label, bod.delivery_method as delivery_method FROM bss_order bo inner join bss_order_extends boe on bo.order_id = boe.order_id LEFT JOIN sys_dict_data sdd2 on sdd2.dict_value = boe.proxy_order_ch and sdd2.dict_type = 'bss_proxy_order_ch' LEFT JOIN sys_dict_data sdd on sdd.dict_value = bo.status and sdd.dict_type = 'bss_order_status' LEFT JOIN bss_order_delivery bod on bod.order_id = bo.order_id and bod.farmer_id = bo.farmer_id LEFT JOIN bss_order_delivery_item bodi ON bodi.order_id = bo.order_id and bodi.delivery_id = bod.id and bodi.farmer_id = bo.farmer_id
bo.farmer_id = #{farmerId}
and bo.status = #{status}
and bodi.item_name like concat('%', #{itemName} , '%')
and bodi.item_cd like concat('%', #{itemCd} , '%')
and LEFT(bo.order_time, 10) >= #{orderDate.startDate}
and LEFT(bo.order_time, 10) <= #{orderDate.endDate}
and bo.customer_name like concat('%', #{customerName} , '%')
and bod.delivery_customer_name like concat('%', #{deliveryCustomerName} , '%')
and bo.delivery_plan_date >= #{deliveryPlanDate.startDate}
and bo.delivery_plan_date <= #{deliveryPlanDate.endDate}
and bod.delivery_tracking_no like concat('%', #{deliveryTrackingNo} , '%')
and (convert_from(decrypt_iv(decode(NULLIF(bo.phone_number, ''), 'base64'), , , 'aes-cbc/pad:pkcs'), 'UTF-8') like CONCAT('%', #{phoneNumber}, '%') or convert_from(decrypt_iv(decode(NULLIF(bod.delivery_phone_number, ''), 'base64'), , , 'aes-cbc/pad:pkcs'), 'UTF-8') like CONCAT('%', #{phoneNumber}, '%'))
AND boe.proxy_order_ch IN
#{itemFlg}
order by bo.delivery_plan_date,bo.order_id,bod.id

SELECT bo.id, bo.order_id, bo.order_time, sdd.dict_label as status_label, bo.customer_name, bod.id as delivery_id, bod.delivery_customer_name, bod.delivery_address as delivery_address, bo.delivery_plan_date, bo.payment_date, bo.ship_date, bo.delivery_date, bod.delivery_tracking_no, bod.delivery_method as delivery_method, bo.phone_number, bod.delivery_phone_number, sdd2.dict_label as proxy_order_ch_label FROM bss_order_delivery bod INNER JOIN bss_order bo on bo.order_id = bod.order_id and bo.farmer_id = bod.farmer_id INNER JOIN bss_order_extends boe on bo.order_id = boe.order_id LEFT JOIN sys_dict_data sdd on sdd.dict_value = bo.status and sdd.dict_type = 'bss_order_status' LEFT JOIN bss_order_delivery_item bodi ON bodi.order_id = bo.order_id and bodi.delivery_id = bod.id and bodi.farmer_id = bod.farmer_id LEFT JOIN sys_dict_data sdd2 on sdd2.dict_value = boe.proxy_order_ch and sdd2.dict_type = 'bss_proxy_order_ch'
bod.farmer_id = #{farmerId}
and bo.status = #{status}
AND exists( SELECT bodi.delivery_id FROM bss_order_delivery_item bodi WHERE bodi.order_id = bo.order_id and bodi.delivery_id = bod.id and bodi.farmer_id = bod.farmer_id AND bodi.item_name LIKE concat('%', #{itemName}, '%') )
and LEFT(bo.order_time, 10) >= #{orderDate.startDate}
and LEFT(bo.order_time, 10) <= #{orderDate.endDate}
and bo.customer_name like concat('%', #{customerName} , '%')
and bod.delivery_customer_name like concat('%', #{deliveryCustomerName} , '%')
and bo.delivery_plan_date >= #{deliveryPlanDate.startDate}
and bo.delivery_plan_date <= #{deliveryPlanDate.endDate}
and bod.delivery_tracking_no like concat('%', #{deliveryTrackingNo} , '%')
and bodi.item_cd like concat('%', #{itemCd} , '%')
and (convert_from(decrypt_iv(decode(NULLIF(bo.phone_number, ''), 'base64'), , , 'aes-cbc/pad:pkcs'), 'UTF-8') like CONCAT('%', #{phoneNumber}, '%') or convert_from(decrypt_iv(decode(NULLIF(bod.delivery_phone_number, ''), 'base64'), , , 'aes-cbc/pad:pkcs'), 'UTF-8') like CONCAT('%', #{phoneNumber}, '%'))
AND boe.proxy_order_ch IN
#{itemFlg}
order by bo.delivery_plan_date,bo.order_id
